sys_script.script:
(function executeRule(current, previous /*null when async*/ ) {
    try {

        var eventReceived = 0;
        while (eventReceived == 0) {
            var getEventRec = new GlideRecord("x_hsb11_mss_custod_mss_custody_event_inbound_staging");
            getEventRec.addEncodedQuery("object_idSTARTSWITH" + current.trade_id.trade_id.toString());
            getEventRec.orderByDesc('sys_created_on');
            getEventRec.setLimit(1);
            getEventRec.query();
            if (getEventRec.next()) {

                var unityTimeStamp = getEventRec.source_system_timestamp.getValue();
                eventReceived = 1;
            }
        }
        var updateTrade = new GlideRecord("x_hsb11_mss_c_proc_mss_custody_trade");
        updateTrade.get(current.trade_id.sys_id);

        updateTrade.source_system_time_stamp_market_time = unityTimeStamp;
        updateTrade.update();
    } catch (ex) {
        gs.info('Error received from Business Rule Amend - New Event Update :' + ex);
    }



})(current, previous);
